import{_ as t,I as a,o as n,c as l,b6 as h,J as e}from"./chunks/framework.COUcLbTA.js";const u=JSON.parse('{"title":"数据模型全景（文档 / 图 / 时序 / 向量）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/5-data/data-models.md","filePath":"zh-cn/appendix/5-data/data-models.md"}'),r={name:"zh-cn/appendix/5-data/data-models.md"};function d(p,s,k,o,g,E){const i=a("DataModelsDemo");return n(),l("div",null,[s[0]||(s[0]=h(`<h1 id="数据模型全景-文档-图-时序-向量" tabindex="-1">数据模型全景（文档 / 图 / 时序 / 向量） <a class="header-anchor" href="#数据模型全景-文档-图-时序-向量" aria-label="Permalink to “数据模型全景（文档 / 图 / 时序 / 向量）”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">🎯 核心问题</p><p><strong>为什么不能把所有数据都塞进 MySQL 的表格里？</strong> 当你的数据是社交关系网、每秒百万条的传感器流水、或者 AI 需要理解的语义向量时，关系型表格就力不从心了。不同的数据形态，需要不同的建模方式。</p></div><hr><h2 id="_1-关系型之外-为什么需要其他数据模型" tabindex="-1">1. 关系型之外：为什么需要其他数据模型？ <a class="header-anchor" href="#_1-关系型之外-为什么需要其他数据模型" aria-label="Permalink to “1. 关系型之外：为什么需要其他数据模型？”">​</a></h2><p>关系型数据库（MySQL、PostgreSQL）用&quot;表 + 行 + 列&quot;组织数据，适合结构固定、关系明确的业务数据。但现实世界的数据远不止这一种形态：</p><table tabindex="0"><thead><tr><th>数据形态</th><th>关系型的痛点</th><th>更合适的模型</th></tr></thead><tbody><tr><td>用户画像（字段不固定，嵌套结构）</td><td>频繁 ALTER TABLE，大量 NULL 列</td><td><strong>文档模型</strong></td></tr><tr><td>社交网络（朋友的朋友的朋友）</td><td>多层 JOIN 性能指数级下降</td><td><strong>图模型</strong></td></tr><tr><td>监控指标（每秒百万条写入）</td><td>写入瓶颈，历史数据膨胀</td><td><strong>时序模型</strong></td></tr><tr><td>AI 语义搜索（&quot;意思相近&quot;的内容）</td><td>无法表达语义相似度</td><td><strong>向量模型</strong></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">💡 核心观点</p><p>不是&quot;替代&quot;关系型，而是&quot;补充&quot;。大多数系统的核心业务仍然跑在 MySQL/PostgreSQL 上，但在特定场景引入专用数据模型，能获得数量级的性能提升。</p></div><hr><h2 id="_2-文档模型-document" tabindex="-1">2. 文档模型（Document） <a class="header-anchor" href="#_2-文档模型-document" aria-label="Permalink to “2. 文档模型（Document）”">​</a></h2><h3 id="_2-1-什么是文档模型" tabindex="-1">2.1 什么是文档模型？ <a class="header-anchor" href="#_2-1-什么是文档模型" aria-label="Permalink to “2.1 什么是文档模型？”">​</a></h3><p>文档模型将数据存储为 <strong>JSON/BSON 文档</strong>，每条记录是一个自包含的文档，可以有不同的字段结构。</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user_1001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;张三&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;VIP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;活跃&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;address&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;city&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;北京&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;district&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;朝阳区&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;orders&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;o1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;amount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">299</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;o2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;amount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">599</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>关键特点：</strong></p><ul><li><strong>无 Schema 约束</strong>：不需要预定义表结构，字段随时增减</li><li><strong>嵌套结构</strong>：地址、订单直接嵌在文档里，一次读取全部数据</li><li><strong>水平扩展</strong>：天然适合分片（Sharding），轻松应对海量数据</li></ul><h3 id="_2-2-文档-vs-关系型" tabindex="-1">2.2 文档 vs 关系型 <a class="header-anchor" href="#_2-2-文档-vs-关系型" aria-label="Permalink to “2.2 文档 vs 关系型”">​</a></h3><table tabindex="0"><thead><tr><th>对比维度</th><th>关系型（MySQL）</th><th>文档型（MongoDB）</th></tr></thead><tbody><tr><td>数据结构</td><td>固定 Schema，ALTER TABLE 修改</td><td>灵活 Schema，随时加字段</td></tr><tr><td>嵌套数据</td><td>需要多表 JOIN</td><td>直接嵌套在文档中</td></tr><tr><td>跨记录关联</td><td>JOIN 很强</td><td>关联查询较弱</td></tr><tr><td>适合场景</td><td>结构稳定的业务数据</td><td>结构多变的内容数据</td></tr></tbody></table><h3 id="_2-3-典型场景" tabindex="-1">2.3 典型场景 <a class="header-anchor" href="#_2-3-典型场景" aria-label="Permalink to “2.3 典型场景”">​</a></h3><ul><li><strong>CMS 内容管理</strong>：文章、评论、标签结构各异</li><li><strong>用户画像</strong>：不同用户有不同的属性字段</li><li><strong>商品目录</strong>：手机有&quot;屏幕尺寸&quot;，食品有&quot;保质期&quot;，字段完全不同</li><li><strong>配置中心</strong>：各服务的配置结构不统一</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ 常见误区</p><p>&quot;MongoDB 不需要设计数据结构&quot; —— 错！文档模型同样需要认真设计：嵌套层级不宜过深，频繁更新的子文档应该拆分为独立集合。</p></div><hr><h2 id="_3-图模型-graph" tabindex="-1">3. 图模型（Graph） <a class="header-anchor" href="#_3-图模型-graph" aria-label="Permalink to “3. 图模型（Graph）”">​</a></h2><h3 id="_3-1-什么是图模型" tabindex="-1">3.1 什么是图模型？ <a class="header-anchor" href="#_3-1-什么是图模型" aria-label="Permalink to “3.1 什么是图模型？”">​</a></h3><p>图模型用 <strong>节点（Node）</strong> 和 <strong>边（Edge）</strong> 表达实体及其关系。每个节点是一个实体，每条边是一个关系，节点和边都可以携带属性。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(张三) --[关注]--&gt; (李四) --[关注]--&gt; (王五)</span></span>
<span class="line"><span>   |                                    |</span></span>
<span class="line"><span>   +--------[购买]----&gt; (iPhone) &lt;--[购买]--+</span></span></code></pre></div><h3 id="_3-2-图模型的杀手级能力-多跳查询" tabindex="-1">3.2 图模型的杀手级能力：多跳查询 <a class="header-anchor" href="#_3-2-图模型的杀手级能力-多跳查询" aria-label="Permalink to “3.2 图模型的杀手级能力：多跳查询”">​</a></h3><p><strong>场景</strong>：在社交网络中找&quot;朋友的朋友的朋友&quot;</p><p>关系型做法（3 层 JOIN）：</p><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT DISTINCT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> f3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">name</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> friends f1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">JOIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> friends f2 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> f1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">friend_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> f2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">user_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">JOIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> friends f3 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> f2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">friend_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> f3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">user_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> f1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">user_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>图数据库做法（Cypher 查询语言）：</p><div class="language-cypher"><button title="Copy Code" class="copy"></button><span class="lang">cypher</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MATCH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (me)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">[:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">FOLLOWS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*1..3</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">]</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(target)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> me.name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;张三&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RETURN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DISTINCT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> target.name</span></span></code></pre></div><p>关系型每多一跳，就多一次 JOIN，性能指数级下降。图数据库通过指针直接遍历关系，多跳查询性能几乎不变。</p><h3 id="_3-3-典型场景" tabindex="-1">3.3 典型场景 <a class="header-anchor" href="#_3-3-典型场景" aria-label="Permalink to “3.3 典型场景”">​</a></h3><ul><li><strong>社交网络</strong>：好友推荐、共同关注、影响力传播</li><li><strong>知识图谱</strong>：实体关系推理（&quot;谁是谁的老师的学生&quot;）</li><li><strong>欺诈检测</strong>：发现资金环路、关联账户网络</li><li><strong>推荐系统</strong>：基于用户-商品-标签的关系图推荐</li></ul><hr><h2 id="_4-时序模型-time-series" tabindex="-1">4. 时序模型（Time-Series） <a class="header-anchor" href="#_4-时序模型-time-series" aria-label="Permalink to “4. 时序模型（Time-Series）”">​</a></h2><h3 id="_4-1-什么是时序模型" tabindex="-1">4.1 什么是时序模型？ <a class="header-anchor" href="#_4-1-什么是时序模型" aria-label="Permalink to “4.1 什么是时序模型？”">​</a></h3><p>时序模型以 <strong>时间戳</strong> 为主轴，专门优化&quot;按时间顺序写入、按时间范围查询&quot;的场景。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>timestamp            device      cpu_usage   memory</span></span>
<span class="line"><span>2024-01-15 10:00:01  server-01   45%         12.3GB</span></span>
<span class="line"><span>2024-01-15 10:00:02  server-01   67%         12.5GB</span></span>
<span class="line"><span>2024-01-15 10:00:03  server-01   92%         14.1GB</span></span></code></pre></div><h3 id="_4-2-为什么不用-mysql-存时序数据" tabindex="-1">4.2 为什么不用 MySQL 存时序数据？ <a class="header-anchor" href="#_4-2-为什么不用-mysql-存时序数据" aria-label="Permalink to “4.2 为什么不用 MySQL 存时序数据？”">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>MySQL</th><th>时序数据库（InfluxDB）</th></tr></thead><tbody><tr><td>写入速度</td><td>万级/秒</td><td><strong>百万级/秒</strong></td></tr><tr><td>历史数据</td><td>手动清理，表越来越大</td><td><strong>自动过期策略</strong>（TTL）</td></tr><tr><td>聚合查询</td><td>GROUP BY 慢</td><td><strong>内置降采样</strong>（5 秒 → 1 分钟均值）</td></tr><tr><td>存储效率</td><td>通用存储，空间浪费</td><td><strong>列式压缩</strong>，节省 90% 空间</td></tr></tbody></table><h3 id="_4-3-典型场景" tabindex="-1">4.3 典型场景 <a class="header-anchor" href="#_4-3-典型场景" aria-label="Permalink to “4.3 典型场景”">​</a></h3><ul><li><strong>服务器监控</strong>：CPU、内存、磁盘每秒采集</li><li><strong>IoT 传感器</strong>：温度、湿度、GPS 轨迹</li><li><strong>金融行情</strong>：股票价格、交易量的秒级数据</li><li><strong>日志分析</strong>：应用日志的时间线聚合</li></ul><hr><h2 id="_5-向量模型-vector" tabindex="-1">5. 向量模型（Vector） <a class="header-anchor" href="#_5-向量模型-vector" aria-label="Permalink to “5. 向量模型（Vector）”">​</a></h2><h3 id="_5-1-什么是向量模型" tabindex="-1">5.1 什么是向量模型？ <a class="header-anchor" href="#_5-1-什么是向量模型" aria-label="Permalink to “5.1 什么是向量模型？”">​</a></h3><p>向量模型将文本、图片、音频等非结构化数据通过 <strong>Embedding 模型</strong> 转换为高维数字向量，然后通过计算向量之间的距离来衡量语义相似度。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;好吃的日料&quot; → Embedding → [0.82, 0.15, 0.91, 0.33, ...]</span></span>
<span class="line"><span>                                    ↓ 余弦相似度</span></span>
<span class="line"><span>&quot;银座寿司之神&quot;  → [0.80, 0.18, 0.89, ...] → 96% 相似</span></span>
<span class="line"><span>&quot;意大利披萨&quot;    → [0.12, 0.85, 0.20, ...] → 31% 相似</span></span></code></pre></div><h3 id="_5-2-向量搜索-vs-关键词搜索" tabindex="-1">5.2 向量搜索 vs 关键词搜索 <a class="header-anchor" href="#_5-2-向量搜索-vs-关键词搜索" aria-label="Permalink to “5.2 向量搜索 vs 关键词搜索”">​</a></h3><table tabindex="0"><thead><tr><th>对比</th><th>关键词搜索（LIKE / 全文索引）</th><th>向量搜索</th></tr></thead><tbody><tr><td>搜索方式</td><td>精确匹配字符串</td><td>语义相似度匹配</td></tr><tr><td>&quot;好吃的日料&quot;</td><td>只能匹配包含&quot;日料&quot;的文本</td><td>能找到&quot;寿司&quot;&quot;刺身&quot;&quot;居酒屋&quot;</td></tr><tr><td>多语言</td><td>需要分别处理</td><td>跨语言语义理解</td></tr><tr><td>多模态</td><td>仅文本</td><td>文本、图片、音频统一检索</td></tr></tbody></table><h3 id="_5-3-典型场景" tabindex="-1">5.3 典型场景 <a class="header-anchor" href="#_5-3-典型场景" aria-label="Permalink to “5.3 典型场景”">​</a></h3><ul><li><strong>RAG（检索增强生成）</strong>：为 LLM 提供相关知识片段</li><li><strong>语义搜索</strong>：理解用户意图而非关键词</li><li><strong>以图搜图</strong>：上传一张图，找到视觉相似的图片</li><li><strong>推荐系统</strong>：基于内容语义的相似推荐</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 向量数据库的选择</p><ul><li><strong>独立向量数据库</strong>：Pinecone、Milvus、Weaviate —— 专注向量检索，性能最优</li><li><strong>传统数据库扩展</strong>：pgvector（PostgreSQL）、Atlas Vector Search（MongoDB）—— 减少架构复杂度</li><li><strong>内存向量库</strong>：FAISS、Annoy —— 适合小规模、低延迟场景</li></ul></div><hr><h2 id="_6-选型决策-如何选择数据模型" tabindex="-1">6. 选型决策：如何选择数据模型？ <a class="header-anchor" href="#_6-选型决策-如何选择数据模型" aria-label="Permalink to “6. 选型决策：如何选择数据模型？”">​</a></h2><table tabindex="0"><thead><tr><th>你的数据长什么样？</th><th>推荐模型</th><th>代表产品</th></tr></thead><tbody><tr><td>结构固定，关系明确（订单、用户）</td><td>关系型</td><td>MySQL、PostgreSQL</td></tr><tr><td>结构灵活，嵌套层级多（内容、配置）</td><td>文档型</td><td>MongoDB、DynamoDB</td></tr><tr><td>实体之间关系复杂，需要多跳遍历</td><td>图</td><td>Neo4j、Amazon Neptune</td></tr><tr><td>按时间顺序写入，按时间范围查询</td><td>时序</td><td>InfluxDB、TimescaleDB</td></tr><tr><td>非结构化数据，需要语义相似度搜索</td><td>向量</td><td>Pinecone、Milvus、pgvector</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">🎯 实战建议</p><p>现代系统通常是<strong>多模型混用</strong>：</p><ul><li><strong>核心业务</strong>用 PostgreSQL（关系型）</li><li><strong>用户行为日志</strong>用 InfluxDB（时序）</li><li><strong>AI 知识库</strong>用 Milvus + pgvector（向量）</li><li><strong>推荐引擎</strong>用 Neo4j（图）</li></ul><p>不要追求&quot;一个数据库解决所有问题&quot;，而是让每种数据找到最合适的家。</p></div>`,56)),e(i)])}const y=t(r,[["render",d]]);export{u as __pageData,y as default};
